models.css:
.card { font-family: "Microsoft YaHei", "PingFang SC", "Noto Sans CJK SC", sans-serif; text-align: center;
        background: #fffdf6; color: #222; padding: 14px; }
.kind { display: inline-block; font-size: 14px; color: #fff; background: #3a7bd5;
        border-radius: 12px; padding: 2px 12px; margin-bottom: 10px; }
.imgs { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.imgs figure { margin: 0; flex: 1 1 280px; max-width: 480px; }
.imgs img { width: 100%; border-radius: 10px; }
.imgs figcaption { font-size: 28px; font-weight: bold; color: #d9534f; }
.ask { font-size: 24px; margin: 14px 0; line-height: 1.5; }
.answer { font-size: 44px; font-weight: bold; color: #2e7d32; margin: 12px 0; }
.tip { font-size: 15px; color: #666; background: #f3f0e6; border-radius: 8px;
       padding: 8px 12px; margin-top: 14px; text-align: left; line-height: 1.6; }
.card.nightMode, .nightMode .card { background: #222; color: #eee; }
.nightMode .answer { color: #7fd184; }
.nightMode .tip { background: #333; color: #bbb; }
